use proptest::prelude::*;
use ripplemq::codec::{decode, encode, Frame};

fn arb_frame() -> impl Strategy<Value = Frame> {
    ("[a-z0-9._-]{1,64}", any::<u16>(), any::<u64>(), prop::collection::vec(any::<u8>(), 0..4096))
        .prop_map(|(topic, partition, offset, payload)| Frame { topic, partition, offset, payload })
}

proptest! {
    #[test]
    fn roundtrip(f in arb_frame()) {
        let bytes = encode(&f);
        let (g, used) = decode(&bytes).unwrap();
        prop_assert_eq!(used, bytes.len());
        prop_assert_eq!(g, f);
    }

    #[test]
    fn decode_never_panics(buf in prop::collection::vec(any::<u8>(), 0..512)) {
        let _ = decode(&buf);
    }

    #[test]
    fn truncated_frame_is_incomplete(f in arb_frame(), cut in 1usize..16) {
        let bytes = encode(&f);
        let cut = cut.min(bytes.len());
        prop_assert!(decode(&bytes[..bytes.len() - cut]).is_err());
    }
}
